import { createHash } from 'node:crypto';
const menu = [
  { nama: 'Kopi Susu', harga: 18000, jumlah: 2 },
  { nama: 'Roti Bakar', harga: 15000, jumlah: 1 },
];
const pajak = Number(process.env.PAJAK ?? '10');
const isi = menu.map((m) => `${m.nama} x${m.jumlah}`).join('|');
const kode = createHash('sha256').update(isi).digest('hex').slice(0, 6).toUpperCase();
console.log('Struk #' + kode);
let subtotal = 0;
for (const m of menu) {
  const harga = m.harga * m.jumlah;
  subtotal += harga;
  console.log(`${m.nama} x${m.jumlah}`.padEnd(16) + String(harga).padStart(7));
}
const total = Math.round(subtotal * (1 + pajak / 100));
console.log('Total'.padEnd(16) + String(total).padStart(7));

