const pesanan = [
  { nama: 'Teh Tarik', harga: 12000 },
  { nama: 'Nasi Uduk', harga: 30000 },
];
for (const p of pesanan) console.log(p.nama.padEnd(12) + String(p.harga).padStart(6));
const total = pesanan.reduce((a, p) => a + p.harga, 0);
console.log('Total'.padEnd(12) + String(total).padStart(6));
